const Fastify = require('/tmp/cxbench/325682c9e5-mcp/fastify')

const schema = {
  type: 'object',
  properties: {
    length: { anyOf: [{ type: 'null' }, { type: 'number' }] }
  }
}

async function main () {
  const app = Fastify()
  app.post('/', { schema: { body: schema } }, (req) => req.body)
  const r = await app.inject({ method: 'POST', url: '/', payload: { length: 0 } })
  console.log('body:', r.body)

  const app2 = Fastify()
  app2.get('/', { schema: { querystring: schema } }, (req) => req.query)
  const r2 = await app2.inject({ method: 'GET', url: '/?length=0' })
  console.log('querystring:', r2.body)

  const app3 = Fastify()
  app3.post('/', { schema: { body: { type: 'object', properties: { length: { type: 'number', nullable: true } } } } }, (req) => req.body)
  const r3 = await app3.inject({ method: 'POST', url: '/', payload: { length: 0 } })
  console.log('nullable kw:', r3.body)
}

main()
